from unittest.mock import Mock

import pytest
from fastapi import APIRouter, FastAPI
from fastapi.routing import APIRoute
from fastapi.testclient import TestClient
from pydantic import BaseModel


@pytest.mark.parametrize("use_router", [False, True])
def test_include_in_schema_if(use_router: bool):
    app = FastAPI()
    router = APIRouter() if use_router else app
    condition = Mock(side_effect=lambda: False)

    class Feature(BaseModel):
        enabled: bool

    @router.get("/public")
    def public():
        return {"public": True}

    @router.get("/feature-flag", include_in_schema_if=condition)
    def feature_flag() -> Feature:
        return Feature(enabled=True)

    if use_router:
        app.include_router(router)

    condition.assert_not_called()
    client = TestClient(app)
    response = client.get("/openapi.json")
    assert response.status_code == 200
    schema = response.json()
    assert "/public" in schema["paths"]
    assert "/feature-flag" not in schema["paths"]
    assert "Feature" not in schema.get("components", {}).get("schemas", {})
    condition.assert_called_once_with()
    assert client.get("/feature-flag").json() == {"enabled": True}

    condition.side_effect = lambda: True
    condition.reset_mock()
    # FastAPI caches OpenAPI; clear it to regenerate with the current condition.
    app.openapi_schema = None
    response = client.get("/openapi.json")
    assert response.status_code == 200
    schema = response.json()
    assert "/public" in schema["paths"]
    assert "/feature-flag" in schema["paths"]
    assert "Feature" in schema["components"]["schemas"]
    condition.assert_called_once_with()


@pytest.mark.parametrize("method", ["get", "put", "post", "delete", "options", "head", "patch", "trace", "api_route"])
@pytest.mark.parametrize("use_router", [False, True])
def test_decorators_propagate_condition(method: str, use_router: bool):
    app = FastAPI()
